  "inlineSchema": "// Prisma schema — backend-api\n// 7 entidades de functional-design/entities.md: User, Session, Vendor,\n// CommissionTier, DailySale, CommissionPeriod, Notification.\n// Fuente: aidlc/.../functional-design/entities.md\n\ngenerator client {\n  provider = \"prisma-client-js\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n  url      = env(\"DATABASE_URL\")\n}\n\nenum Role {\n  vendedor\n  supervisor\n}\n\nenum Channel {\n  preventa\n  autoventa\n}\n\nenum TierType {\n  por_devolucion\n  por_efectividad\n}\n\nenum SyncStatus {\n  synced\n  pending\n}\n\nenum NotificationType {\n  umbral_venta\n  umbral_devolucion\n  manual\n}\n\n/// Identidad y credenciales de quien se autentica (vendedor o supervisor).\nmodel User {\n  id           String   @id @default(cuid())\n  role         Role\n  /// requerido solo cuando role=vendedor; único entre todos los User con role=vendedor\n  username     String?  @unique\n  /// requerido solo cuando role=vendedor; solo interno, nunca se expone en response\n  passwordHash String?\n  /// requerido solo cuando role=supervisor; solo interno, nunca se expone en response\n  pin          String?\n  active       Boolean  @default(true)\n  createdAt    DateTime @default(now())\n  updatedAt    DateTime @updatedAt\n\n  sessions Session[]\n  vendor   Vendor?\n\n  @@map(\"users\")\n}\n\n/// Sesión activa emitida al autenticar. Ninguna Session expira por tiempo\n/// transcurrido (BR1.4, BR1.5) — solo termina por logout explícito o revocación manual.\nmodel Session {\n  id        String    @id @default(cuid())\n  /// token opaco — lookup por token en cada petición protegida\n  token     String    @unique @default(cuid())\n  userId    String\n  createdAt DateTime  @default(now())\n  /// siempre ausente/nulo en este MVP — ningún rol tiene sesión con expiración por tiempo\n  expiresAt DateTime?\n  revokedAt DateTime?\n\n  user User @relation(fields: [userId], references: [id])\n\n  @@index([userId])\n  @@map(\"sessions\")\n}\n\n/// Vendedor del roster, con su ruta, canal y presupuesto vigente.\nmodel Vendor {\n  id        String   @id @default(cuid())\n  userId    String   @unique\n  route     String\n  name      String\n  channel   Channel\n  budget    Decimal  @db.Decimal(14, 2)\n  active    Boolean  @default(true)\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  user              User               @relation(fields: [userId], references: [id])\n  dailySales        DailySale[]\n  commissionPeriods CommissionPeriod[]\n  notifications     Notification[]\n\n  @@index([channel])\n  @@index([route])\n  @@map(\"vendors\")\n}\n\n/// Tramo de comisión configurado por canal, con su orden relativo.\nmodel CommissionTier {\n  id             String   @id @default(cuid())\n  channel        Channel\n  tierType       TierType\n  order          Int\n  /// porcentaje: umbral de indicador de devolución o de efectividad de venta sobre presupuesto\n  thresholdValue Decimal  @db.Decimal(7, 3)\n  /// porcentaje aplicado sobre la venta acumulada del período (BR4.3)\n  commissionRate Decimal  @db.Decimal(7, 4)\n  createdAt      DateTime @default(now())\n  updatedAt      DateTime @updatedAt\n\n  @@index([channel, order])\n  @@map(\"commission_tiers\")\n}\n\n/// Venta y devoluciones de un vendedor en un día, con soporte para registro sin conexión.\nmodel DailySale {\n  id         String     @id @default(cuid())\n  vendorId   String\n  saleDate   DateTime   @db.Date\n  amount     Decimal    @db.Decimal(14, 2)\n  returns    Decimal    @db.Decimal(14, 2)\n  syncStatus SyncStatus @default(synced)\n  closed     Boolean    @default(false)\n  createdAt  DateTime   @default(now())\n  updatedAt  DateTime   @updatedAt\n\n  vendor Vendor @relation(fields: [vendorId], references: [id])\n\n  /// único por (vendorId, saleDate) — clave de idempotencia de sincronización (NFR4.2, ADR-004)\n  @@unique([vendorId, saleDate])\n  @@map(\"daily_sales\")\n}\n\n/// Agregado mensual de comisión, venta e indicador de devolución de un vendedor.\nmodel CommissionPeriod {\n  id                 String    @id @default(cuid())\n  vendorId           String\n  /// formato AAAA-MM\n  periodMonth        String\n  accumulatedSales   Decimal   @default(0) @db.Decimal(14, 2)\n  accumulatedReturns Decimal   @default(0) @db.Decimal(14, 2)\n  /// accumulatedReturns / accumulatedSales; 0 cuando accumulatedSales es 0 (BR8.1)\n  returnRate         Decimal   @default(0) @db.Decimal(9, 6)\n  commissionEarned   Decimal   @default(0) @db.Decimal(14, 2)\n  closed             Boolean   @default(false)\n  closedAt           DateTime?\n  createdAt          DateTime  @default(now())\n  updatedAt          DateTime  @updatedAt\n\n  vendor Vendor @relation(fields: [vendorId], references: [id])\n\n  @@unique([vendorId, periodMonth])\n  @@index([closed, vendorId])\n  @@map(\"commission_periods\")\n}\n\n/// Notificación entregada a un vendedor — de umbral automático o manual del supervisor.\n/// También funciona como el registro de seguimiento de qué umbrales ya se notificaron\n/// en el período vigente (Q6 de functional-design-questions.md) — de ahí el campo\n/// interno periodMonth, no expuesto en el contrato, usado solo para la consulta de\n/// no-duplicación de BR7.2/BR8.2.\nmodel Notification {\n  id                 String           @id @default(cuid())\n  vendorId           String\n  type               NotificationType\n  /// presente solo cuando type≠manual\n  thresholdCrossed   Decimal?         @db.Decimal(7, 3)\n  /// presente solo cuando type=umbral_devolucion y los tramos del canal están en orden (BR8.3)\n  earningOpportunity Json?\n  message            String\n  sentAt             DateTime         @default(now())\n  read               Boolean          @default(false)\n  /// campo interno de persistencia (no en el contrato) — período vigente al momento del envío,\n  /// usado como parte de la clave de no-duplicación (vendorId, type, thresholdCrossed, periodMonth)\n  periodMonth        String\n\n  vendor Vendor @relation(fields: [vendorId], references: [id])\n\n  @@index([vendorId, type, periodMonth])\n  @@map(\"notifications\")\n}\n",
